// Get the sub-workflow result and the original test case
var result = $input.first().json;
var testCase = $('Loop Over Tests').first().json;

var testName = testCase._testName;
var testType = testCase._testType || 'regular';
var expectReview = testCase._expectReviewNeeded;
var scenario = testCase._scenario;
var bugDescription = testCase._bugDescription || '';

var testPassed = false;
var status = '';
var detail = '';

if (testType === 'bug') {
  // Bug tests: PASS if the sub-workflow returned ANY response (didn't crash)
  var hasResponse = result != null && (result.overallAssessment != null || result.passed != null || result.confidenceScore != null);
  testPassed = hasResponse;
  status = testPassed ? 'TEST PASSED' : 'TEST FAILED';
  detail = testPassed
    ? 'Sub-workflow handled gracefully. Assessment: ' + (result.overallAssessment || 'N/A') + '. Score: ' + (result.confidenceScore != null ? result.confidenceScore : 'N/A')
    : 'Sub-workflow crashed or returned empty response.';
} else {
  // Regular tests: compare needsHumanReview against expected
  var actualReview = result.needsHumanReview === true;
  testPassed = (expectReview === actualReview);
  status = testPassed ? 'TEST PASSED' : 'TEST FAILED';
  if (!testPassed) {
    if (expectReview) {
      detail = 'Expected sub-workflow to FLAG this output for review, but it PASSED it through.';
    } else {
      detail = 'Expected sub-workflow to PASS this output, but it FLAGGED it for review.';
    }
  } else {
    detail = expectReview
      ? 'Correctly flagged for human review.'
      : 'Correctly passed without flagging.';
  }
}

var resultObj = {
  testName: testName,
  testType: testType,
  scenario: scenario,
  testStatus: status,
  testPassed: testPassed,
  detail: detail,
  bugDescription: bugDescription,
  expectedReviewNeeded: expectReview,
  actualReviewNeeded: result.needsHumanReview === true,
  confidenceScore: result.confidenceScore != null ? result.confidenceScore : 'N/A',
  overallAssessment: result.overallAssessment || 'N/A',
  passed: result.passed != null ? result.passed : 'N/A',
  reviewLevel: result.reviewLevel || 'NONE',
  decisionSummary: result.decisionSummary || '',
  flaggedIssuesCount: result.flaggedIssues ? result.flaggedIssues.length : 0,
  unsourcedClaimCount: result.unsourcedClaimCount != null ? result.unsourcedClaimCount : 0,
  totalClaimsChecked: result.totalClaimsChecked != null ? result.totalClaimsChecked : 0
};

// Accumulate ALL results in static data
var staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData._testResults)) {
  staticData._testResults = [];
}
staticData._testResults.push(resultObj);

// Accumulate bug results separately for Retry Queue
if (testType === 'bug') {
  if (!Array.isArray(staticData._retryQueueEntries)) {
    staticData._retryQueueEntries = [];
  }
  staticData._retryQueueEntries.push({
    Timestamp: new Date().toISOString(),
    OriginalExecutionId: result.executionId || 'N/A',
    WorkflowName: testCase.workflowName,
    Status: 'PENDING',
    RetryCount: 0,
    LastRetry: '',
    ErrorMessage: bugDescription,
    workflowName: testCase.workflowName,
    aiTaskType: testCase.aiTaskType,
    originalInput: testCase.originalInput,
    aiOutput: testCase.aiOutput || '',
    aiModel: testCase.aiModel || '',
    domainContext: testCase.domainContext || '',
    strictnessThreshold: testCase.strictnessThreshold != null ? testCase.strictnessThreshold : 80,
    notifyEmail: testCase.notifyEmail || '',
    customValidationInstructions: testCase.customValidationInstructions || ''
  });
}

return [{ json: resultObj }];

// Read all accumulated test results from workflow static data
var staticData = $getWorkflowStaticData('global');
var allResults = staticData._testResults || [];

// Clear the test results accumulator
delete staticData._testResults;

// Separate regular and bug tests
var regularResults = [];
var bugResults = [];
for (var i = 0; i < allResults.length; i++) {
  if (allResults[i].testType === 'bug') {
    bugResults.push(allResults[i]);
  } else {
    regularResults.push(allResults[i]);
  }
}

var totalTests = allResults.length;
var testsPassed = 0;
var testsFailed = 0;

// Build regular test rows
var regularRows = '';
for (var i = 0; i < regularResults.length; i++) {
  var r = regularResults[i];
  if (r.testPassed) testsPassed++;
  else testsFailed++;

  var statusColor = r.testPassed ? '#28a745' : '#dc3545';
  var statusIcon = r.testPassed ? 'PASS' : 'FAIL';

  regularRows += '<tr>' +
    '<td style="padding:10px;border:1px solid #ddd;">' + (i + 1) + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;font-weight:bold;color:' + statusColor + ';">' + statusIcon + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;">' + r.testName + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;text-align:center;">' + r.confidenceScore + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;">' + r.overallAssessment + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;text-align:center;">' + (r.expectedReviewNeeded ? 'Yes' : 'No') + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;text-align:center;">' + (r.actualReviewNeeded ? 'Yes' : 'No') + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;">' + r.detail + '</td>' +
    '</tr>';
}

// Build bug test rows
var bugRows = '';
for (var j = 0; j < bugResults.length; j++) {
  var b = bugResults[j];
  if (b.testPassed) testsPassed++;
  else testsFailed++;

  var bStatusColor = b.testPassed ? '#28a745' : '#dc3545';
  var bStatusIcon = b.testPassed ? 'PASS' : 'FAIL';

  bugRows += '<tr>' +
    '<td style="padding:10px;border:1px solid #ddd;">' + (j + 1) + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;font-weight:bold;color:' + bStatusColor + ';">' + bStatusIcon + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;">' + b.testName + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;">' + b.bugDescription + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;text-align:center;">' + b.confidenceScore + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;">' + b.overallAssessment + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;">' + b.detail + '</td>' +
    '</tr>';
}

var overallColor = testsFailed === 0 ? '#28a745' : '#dc3545';
var overallStatus = testsFailed === 0 ? 'ALL TESTS PASSED' : testsFailed + ' TEST(S) FAILED';

var reportHtml = '<div style="font-family:Arial,sans-serif;max-width:1000px;margin:0 auto;">' +
  '<div style="background:' + overallColor + ';color:white;padding:20px;border-radius:8px 8px 0 0;">' +
  '<h2 style="margin:0;">AI Validation Test Harness Results</h2>' +
  '<p style="margin:6px 0 0;font-size:18px;">' + overallStatus + ' (' + testsPassed + '/' + totalTests + ')</p>' +
  '</div>' +
  '<div style="padding:16px;border:1px solid #ddd;border-top:none;">' +
  '<h3 style="margin-top:0;">Regular Validation Tests (' + regularResults.length + ')</h3>' +
  '<table style="width:100%;border-collapse:collapse;">' +
  '<tr style="background:#f5f5f5;">' +
  '<th style="padding:10px;border:1px solid #ddd;">#</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Result</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Test Scenario</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Score</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Assessment</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Expected Review</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Actual Review</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Detail</th>' +
  '</tr>' +
  regularRows +
  '</table>' +
  '<h3 style="margin-top:24px;">Bug / Edge Case Tests (' + bugResults.length + ')</h3>' +
  '<p style="color:#666;margin-top:0;">These test error handling. PASS = sub-workflow handled gracefully without crashing. Results logged to Retry Queue sheet.</p>' +
  '<table style="width:100%;border-collapse:collapse;">' +
  '<tr style="background:#fff3cd;">' +
  '<th style="padding:10px;border:1px solid #ddd;">#</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Result</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Test Scenario</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Bug Description</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Score</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Assessment</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Detail</th>' +
  '</tr>' +
  bugRows +
  '</table>' +
  '<div style="margin-top:16px;padding:12px;background:#f9f9f9;border-radius:4px;">' +
  '<strong>Summary:</strong> ' + totalTests + ' tests executed (' + regularResults.length + ' regular + ' + bugResults.length + ' bug). ' +
  '<span style="color:#28a745;font-weight:bold;">' + testsPassed + ' passed</span>, ' +
  '<span style="color:' + (testsFailed > 0 ? '#dc3545' : '#28a745') + ';font-weight:bold;">' + testsFailed + ' failed</span>. ' +
  (bugResults.length > 0 ? bugResults.length + ' entries written to Retry Queue sheet.' : '') +
  '</div>' +
  '</div></div>';

var subject = testsFailed === 0
  ? '[TEST HARNESS] ALL PASSED - ' + testsPassed + '/' + totalTests + ' scenarios'
  : '[TEST HARNESS] ' + testsFailed + ' FAILED - ' + testsPassed + '/' + totalTests + ' passed';

return [{
  json: {
    totalTests: totalTests,
    testsPassed: testsPassed,
    testsFailed: testsFailed,
    allPassed: testsFailed === 0,
    overallStatus: overallStatus,
    emailSubject: subject,
    reportHtml: reportHtml,
    regularCount: regularResults.length,
    bugCount: bugResults.length,
    results: allResults
  }
}];

// Read accumulated retry queue entries from static data
var staticData = $getWorkflowStaticData('global');
var retryEntries = staticData._retryQueueEntries || [];

// Clear the retry queue accumulator
delete staticData._retryQueueEntries;

// If no bug scenarios ran, return empty array (downstream sheet node won't execute)
if (retryEntries.length === 0) {
  return [];
}

// Return one item per retry queue entry for Google Sheets to append
return retryEntries.map(function(entry) {
  return { json: entry };
});
